#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long mod(long long x) {
    x %= MOD;
    if (x < 0) x += MOD;
    return x;
}

long long mul(long long a, long long b) {
    return (a * b) % MOD;
}

vector<int> getPrimes(int n) {
    vector<int> is_prime(n + 1, 1);
    is_prime[0] = is_prime[1] = 0;
    vector<int> primes;
    for (int i = 2; i <= n; ++i) {
        if (is_prime[i]) primes.push_back(i);
        for (int p : primes) {
            if (1LL * i * p > n) break;
            is_prime[i * p] = 0;
            if (i % p == 0) break;
        }
    }
    return is_prime;
}

long long solve(long long n, long long m) {
    vector<int> p = getPrimes(n + 10);
    __int128 pre = 1;
    long long M = mod(m);
    long long res = 0;
    long long ans = M;
    long long ans1 = M;
    for (long long i = 2; i <= n; ++i) {
        if (pre <= m && p[i]) {
            pre = pre * i;
        }
        if (pre > m) {
            ans = 0;
        } else {
            long long div = m / (long long)pre;
            ans = mul(ans, div % MOD);
        }
        ans1 = mul(ans1, M);
        res = mod(res + ans1 - ans);
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n, m;
    if (!(cin >> n >> m)) return 0;
    cout << solve(n, m) << "\n";
    return 0;
}

